use vstd::prelude::*;

verus! {

fn frombuffer(buffer: &Vec<u8>, count: usize, offset: usize) -> (out: Vec<u8>)
    requires
        offset + count <= buffer.len(),
        count == 0 || offset < buffer.len(),
    ensures
        out.len() == count,
        forall|i: int| 0 <= i < count ==> out[i] == buffer[offset + i],
{
    buffer[offset..offset + count].to_vec()
}

}

